// Real Vectorla results for visitors without an image of their own (see
// WorkspacePreview.tsx). Each sample's quick.svg and pro.svg are the engine's
// unedited output for its source image, one per trace mode (generated by
// design/concepts/tools/trace-samples.ts). Files live in public/samples/ and
// load only when a sample is opened.

export type TraceSampleId = 'logo' | 'emblem' | 'emoji'

export interface TraceSample {
  id: TraceSampleId
  source: string
  quick: string
  professional: string
  /** Credit line for the source image; null for Vectorla's own test designs. */
  credit: string | null
}

export const TRACE_SAMPLES: readonly TraceSample[] = [
  {
    id: 'logo',
    source: '/samples/logo/source.jpg',
    quick: '/samples/logo/quick.svg',
    professional: '/samples/logo/pro.svg',
    credit: null,
  },
  {
    id: 'emblem',
    source: '/samples/emblem/source.jpg',
    quick: '/samples/emblem/quick.svg',
    professional: '/samples/emblem/pro.svg',
    credit: null,
  },
  {
    id: 'emoji',
    source: '/samples/emoji/source.png',
    quick: '/samples/emoji/quick.svg',
    professional: '/samples/emoji/pro.svg',
    credit: 'Microsoft Fluent Emoji (MIT)',
  },
]
